import React, {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useRef,
  useState,
} from "react";

import api from "../services/api";

const AppContext = createContext(null);


/* =========================
   CACHE HELPERS
========================= */

const readCache = (key, fallback) => {
  try {
    const value = localStorage.getItem(key);

    return value ? JSON.parse(value) : fallback;
  } catch {
    return fallback;
  }
};


const writeCache = (key, value) => {
  try {
    localStorage.setItem(key, JSON.stringify(value));
  } catch {
    // Ignore cache errors
  }
};


/* =========================
   NORMALIZE BLOCK ID
========================= */

/*
  IMPORTANT:

  Backend kabhi block_id number bhej sakta hai
  aur frontend/user data me string ho sakta hai.

  Example:
  resource.block_id = 5
  user.block_id = "5"

  Direct comparison fail hota hai.

  Isliye har jagah String use karenge.
*/

const normalizeBlockId = (blockId) => {
  if (
    blockId === null ||
    blockId === undefined ||
    blockId === ""
  ) {
    return null;
  }

  return String(blockId);
};


/* =========================
   NORMALIZE RESOURCES
========================= */

const normalizeResourcesList = (data) => {
  if (Array.isArray(data)) {
    return data;
  }

  /*
    Agar API already object/grouped format bhej rahi ho
    toh usko flat array bana denge.
  */

  if (data && typeof data === "object") {
    return Object.values(data).flat();
  }

  return [];
};


/* =========================
   GROUP RESOURCES BY BLOCK
========================= */

const groupResourcesByBlock = (resourcesData) => {
  const grouped = {};

  const resourcesList =
    normalizeResourcesList(resourcesData);

  resourcesList.forEach((resource) => {
    if (!resource) {
      return;
    }

    const normalizedBlockId =
      normalizeBlockId(resource.block_id);

    /*
      Extra centers ke resources
      alag "extra" key me rahenge.
    */

    const key =
      normalizedBlockId || "extra";

    if (!grouped[key]) {
      grouped[key] = [];
    }

    grouped[key].push(resource);
  });

  return grouped;
};


/* =========================
   APP PROVIDER
========================= */

export const AppProvider = ({ children }) => {

  const initialBlocks =
    readCache("blocks", []);

  const cachedResources =
    readCache("resources", {});

  const initialResources =
    cachedResources &&
    typeof cachedResources === "object"
      ? cachedResources
      : {};

  const initialIncharges =
    readCache("incharges", {});


  const initialDataLoaded =
    Array.isArray(initialBlocks) &&
    initialBlocks.length > 0;


  const [blocks, setBlocks] =
    useState(initialBlocks);

  const [resources, setResources] =
    useState(initialResources);

  const [incharges, setIncharges] =
    useState(initialIncharges);

  const [dataLoaded, setDataLoaded] =
    useState(initialDataLoaded);

  const [prefetching, setPrefetching] =
    useState(false);

  const prefetchStartedRef =
    useRef(false);


  /* =========================
     FETCH INITIAL DATA
  ========================= */

  const fetchInitialData = useCallback(
    async (options = {}) => {

      const force =
        Boolean(options.force);


      if (
        !force &&
        (
          dataLoaded ||
          prefetchStartedRef.current
        )
      ) {
        return;
      }


      prefetchStartedRef.current = true;

      setPrefetching(true);


      try {

        const [
          blocksRes,
          inchargesRes,
          resourcesRes,
        ] = await Promise.all([

          api.get("/blocks", {
            cache: !force,
          }),

          api.get("/incharges", {
            cache: !force,
          }),

          api.get("/all-resources", {
            cache: !force,
          }),

        ]);


        const nextBlocks =
          Array.isArray(blocksRes.data)
            ? blocksRes.data
            : [];


        const nextIncharges =
          inchargesRes.data || {};


        const nextResources =
          groupResourcesByBlock(
            resourcesRes.data || []
          );


        setBlocks(nextBlocks);

        setIncharges(nextIncharges);

        setResources(nextResources);

        setDataLoaded(true);


        writeCache(
          "blocks",
          nextBlocks
        );

        writeCache(
          "incharges",
          nextIncharges
        );

        writeCache(
          "resources",
          nextResources
        );


        localStorage.setItem(
          "dataLoaded",
          "true"
        );


      } catch (error) {

        console.error(
          "Failed to load initial data:",
          error
        );

        throw error;


      } finally {

        prefetchStartedRef.current = false;

        setPrefetching(false);

      }

    },
    [dataLoaded]
  );


  /* =========================
     PRELOAD AFTER LOGIN
  ========================= */

  const preloadAfterLogin = useCallback(
    async (role) => {

      setPrefetching(true);


      try {

        const commonRequests = [

          api.get("/blocks", {
            cache: false,
          }),

          api.get("/incharges", {
            cache: false,
          }),

          api.get("/all-resources", {
            cache: false,
          }),

        ];


        const normalizedRole =
          String(role || "")
            .trim()
            .toLowerCase();


        const roleRequests =
          normalizedRole === "admin"

            ? [

                api.get(
                  "/admin/bookings/pending",
                  { cache: false }
                ),

                api.get(
                  "/admin/schedule",
                  { cache: false }
                ),

                api.get(
                  "/admin/history",
                  { cache: false }
                ),

              ]

            : [

                api.get(
                  "/client/dashboard",
                  { cache: false }
                ),

                api.get(
                  "/client/bookings",
                  { cache: false }
                ),

              ];


        const responses =
          await Promise.all([
            ...commonRequests,
            ...roleRequests,
          ]);


        const [
          blocksRes,
          inchargesRes,
          resourcesRes,
        ] = responses;


        const nextBlocks =
          Array.isArray(blocksRes.data)
            ? blocksRes.data
            : [];


        const nextIncharges =
          inchargesRes.data || {};


        /*
          IMPORTANT:
          Resources ko block_id ke according
          group kar rahe hain.
        */

        const nextResources =
          groupResourcesByBlock(
            resourcesRes.data || []
          );


        setBlocks(nextBlocks);

        setIncharges(nextIncharges);

        setResources(nextResources);

        setDataLoaded(true);


        writeCache(
          "blocks",
          nextBlocks
        );

        writeCache(
          "incharges",
          nextIncharges
        );

        writeCache(
          "resources",
          nextResources
        );


        /* =========================
           ROLE CACHE
        ========================= */

        if (
          normalizedRole === "admin"
        ) {

          localStorage.setItem(
            "adminPendingBookings",
            JSON.stringify(
              responses[3].data || []
            )
          );


          localStorage.setItem(
            "adminSchedule",
            JSON.stringify(
              responses[4].data || []
            )
          );


          localStorage.setItem(
            "adminHistory",
            JSON.stringify(
              responses[5].data || []
            )
          );


        } else {

          localStorage.setItem(
            "dashboard",
            JSON.stringify(
              responses[3].data || {}
            )
          );


          localStorage.setItem(
            "bookings",
            JSON.stringify(
              responses[4].data || []
            )
          );

        }


      } catch (error) {

        console.error(
          "Failed to preload application data:",
          error
        );

        throw error;


      } finally {

        setPrefetching(false);

      }

    },
    []
  );


  /* =========================
     GET BLOCK RESOURCES
  ========================= */

  /*
    Ye function BookingForm me use kar sakte ho.

    Example:

    const blockResources =
      getResourcesForBlock(user.block_id);

    Isse:
    5 aur "5"
    dono properly match honge.
  */

  const getResourcesForBlock =
    useCallback(
      (blockId) => {

        const normalizedBlockId =
          normalizeBlockId(blockId);


        if (!normalizedBlockId) {
          return [];
        }


        return (
          resources[
            normalizedBlockId
          ] || []
        );

      },
      [resources]
    );


  /* =========================
     GET BLOCK DETAILS
  ========================= */

  const getBlockById =
    useCallback(
      (blockId) => {

        const normalizedBlockId =
          normalizeBlockId(blockId);


        if (!normalizedBlockId) {
          return null;
        }


        return (
          blocks.find((block) =>

            normalizeBlockId(
              block.id
            ) === normalizedBlockId

          ) || null
        );

      },
      [blocks]
    );


  /* =========================
     CONTEXT VALUE
  ========================= */

  const value = useMemo(
    () => ({

      blocks,

      resources,

      incharges,

      dataLoaded,

      prefetching,

      fetchInitialData,

      preloadAfterLogin,

      getResourcesForBlock,

      getBlockById,

      setBlocks,

      setResources,

      setIncharges,

    }),

    [
      blocks,
      resources,
      incharges,
      dataLoaded,
      prefetching,
      fetchInitialData,
      preloadAfterLogin,
      getResourcesForBlock,
      getBlockById,
    ]
  );


  return (

    <AppContext.Provider value={value}>

      {children}

    </AppContext.Provider>

  );

};


/* =========================
   CONTEXT HOOK
========================= */

export const useAppContext = () => {

  const context =
    useContext(AppContext);


  if (!context) {

    throw new Error(
      "useAppContext must be used inside AppProvider"
    );

  }


  return context;

};
